import React, { useState, useMemo, useEffect, useRef } from "react";
import { Cable, Gauge, Settings2, AlertTriangle, CheckCircle2, ChevronDown, Layers, ShieldCheck, Download } from "lucide-react";
import jsPDF from "jspdf";
import html2canvas from "html2canvas";

// ---------- Datos técnicos base (referencia práctica RIC N°4 / uso habitual en Chile) ----------
const SECCIONES_MM2 = [1.5, 2.5, 4, 6, 10, 16, 25, 35, 50, 70, 95, 120, 150, 185, 240, 300];

// Equivalencia AWG/kcmil -> mm² (área real de cobre)
const AWG_TABLE = [
  { awg: "14", mm2: 2.08 },
  { awg: "12", mm2: 3.31 },
  { awg: "10", mm2: 5.26 },
  { awg: "8", mm2: 8.37 },
  { awg: "6", mm2: 13.3 },
  { awg: "4", mm2: 21.2 },
  { awg: "3", mm2: 26.7 },
  { awg: "2", mm2: 33.6 },
  { awg: "1", mm2: 42.4 },
  { awg: "1/0", mm2: 53.5 },
  { awg: "2/0", mm2: 67.4 },
  { awg: "3/0", mm2: 85.0 },
  { awg: "4/0", mm2: 107.2 },
  { awg: "250 kcmil", mm2: 126.7 },
  { awg: "300 kcmil", mm2: 152.0 },
  { awg: "350 kcmil", mm2: 177.3 },
  { awg: "400 kcmil", mm2: 202.7 },
  { awg: "500 kcmil", mm2: 253.4 },
];

const MATERIALES = {
  cobre: { nombre: "Cobre", resistividad: 0.0182, color: "#D98A3D", factorAmpacidad: 1 },
  aluminio: { nombre: "Aluminio", resistividad: 0.0294, color: "#9AA4AC", factorAmpacidad: 0.78 },
};

const LOGO_TAU = "data:image/png;base64,";

const REACTANCIA_X0 = 0.00008; // Ω/m, valor típico referencial para cables BT

const LIMITES = [
  { id: "circuito", nombre: "Circuito individual (3%)", valor: 3 },
  { id: "total", nombre: "Alimentador + circuito (5%)", valor: 5 },
  { id: "custom", nombre: "Personalizado", valor: null },
];

// Ampacidad referencial (A) para cobre, aislación PVC/THHN, 3 conductores activos, temp. ambiente estándar
// [soterrado, tuberia, escalerilla/bandeja] — valores orientativos, deben verificarse contra tabla oficial RIC N°4
const CANALIZACIONES = [
  { id: "soterrado", nombre: "Soterrado (ducto/directo)", idx: 0 },
  { id: "tuberia", nombre: "Tubería / conduit", idx: 1 },
  { id: "escalerilla", nombre: "Escalerilla / bandeja", idx: 2 },
];

const AMPACIDAD_CU = {
  1.5: [15, 15.5, 19],
  2.5: [20, 21, 26],
  4: [25, 28, 35],
  6: [32, 36, 45],
  10: [42, 50, 61],
  16: [54, 66, 81],
  25: [70, 84, 106],
  35: [83, 101, 131],
  50: [99, 122, 158],
  70: [125, 149, 200],
  95: [148, 179, 241],
  120: [168, 206, 278],
  150: [190, 225, 318],
  185: [211, 262, 362],
  240: [240, 300, 424],
  300: [265, 340, 486],
};

// Termomagnético — series estándar de corriente nominal (A)
const IN_STANDARD = [6, 10, 16, 20, 25, 32, 40, 50, 63, 80, 100, 125, 160, 200, 250, 315, 400];

// Tipos de carga y curva de disparo magnético recomendada
const TIPOS_CARGA = [
  {
    id: "iluminacion",
    nombre: "Iluminación / resistivo",
    curva: "B",
    rango: "3–5 × In",
    desc: "Cargas resistivas puras o de bajo pico de arranque: iluminación, calefacción, circuitos de tomacorrientes de uso general en instalaciones residenciales con conductores largos.",
  },
  {
    id: "general",
    nombre: "Mixta / tomacorrientes general",
    curva: "C",
    rango: "5–10 × In",
    desc: "Uso general con cargas mixtas: electrodomésticos, equipos electrónicos, pequeños motores monofásicos (refrigeradores, bombas domésticas). Es la curva por defecto más usada en instalaciones de consumo.",
  },
  {
    id: "motor",
    nombre: "Motores / alta corriente de arranque",
    curva: "D",
    rango: "10–20 × In",
    desc: "Motores trifásicos, compresores, transformadores y equipos con corriente de arranque elevada, donde una curva B o C dispararía en falso durante el arranque.",
  },
];

function seccionPorAmpacidad(I, canalIdx, factorMaterial) {
  for (const s of SECCIONES_MM2) {
    const tabla = AMPACIDAD_CU[s];
    if (!tabla) continue;
    const capacidad = tabla[canalIdx] * factorMaterial;
    if (capacidad >= I) return { s, capacidad };
  }
  const last = SECCIONES_MM2[SECCIONES_MM2.length - 1];
  return { s: last, capacidad: AMPACIDAD_CU[last][canalIdx] * factorMaterial };
}

function seccionPorCaida(deltaVMax, calcAt1mm2) {
  const sNecesaria = calcAt1mm2 / deltaVMax;
  const s = SECCIONES_MM2.find((s) => s >= sNecesaria) || SECCIONES_MM2[SECCIONES_MM2.length - 1];
  return { sNecesaria, s };
}

function mm2ToAwg(mm2) {
  const match = AWG_TABLE.find((a) => a.mm2 >= mm2);
  return match ? match.awg : AWG_TABLE[AWG_TABLE.length - 1].awg;
}

function Gauge2({ pct, limite }) {
  const clampedForNeedle = Math.min(pct, limite * 1.5);
  const maxScale = limite * 1.5;
  const angle = (clampedForNeedle / maxScale) * 180 - 90;
  const zoneGreen = (0.8 * limite / maxScale) * 180;
  const zoneAmber = (limite / maxScale) * 180;

  const polarToXY = (cx, cy, r, angDeg) => {
    const rad = (angDeg - 90) * (Math.PI / 180);
    return { x: cx + r * Math.cos(rad), y: cy + r * Math.sin(rad) };
  };
  const arcPath = (startDeg, endDeg, r) => {
    const s = polarToXY(100, 100, r, startDeg);
    const e = polarToXY(100, 100, r, endDeg);
    const largeArc = endDeg - startDeg > 180 ? 1 : 0;
    return `M ${s.x} ${s.y} A ${r} ${r} 0 ${largeArc} 1 ${e.x} ${e.y}`;
  };

  const needleEnd = polarToXY(100, 100, 70, angle);
  const estado = pct <= limite * 0.8 ? "ok" : pct <= limite ? "warn" : "danger";
  const estadoColor = estado === "ok" ? "#4F9B72" : estado === "warn" ? "#D9A441" : "#C1503F";

  return (
    <svg viewBox="0 0 200 120" className="w-full max-w-xs mx-auto">
      <path d={arcPath(0, zoneGreen, 82)} stroke="#3A5A46" strokeWidth="14" fill="none" strokeLinecap="butt" />
      <path d={arcPath(zoneGreen, zoneAmber, 82)} stroke="#6B5730" strokeWidth="14" fill="none" />
      <path d={arcPath(zoneAmber, 180, 82)} stroke="#5B372F" strokeWidth="14" fill="none" />
      <line x1="100" y1="100" x2={needleEnd.x} y2={needleEnd.y} stroke={estadoColor} strokeWidth="3" strokeLinecap="round" />
      <circle cx="100" cy="100" r="5" fill={estadoColor} />
      <text x="100" y="88" textAnchor="middle" fontFamily="IBM Plex Mono, monospace" fontSize="20" fill="#EDEAE3" fontWeight="600">
        {pct.toFixed(2)}%
      </text>
    </svg>
  );
}

function Field({ label, children, hint }) {
  return (
    <div className="mb-4">
      <label className="block text-xs tracking-wide uppercase mb-1.5" style={{ color: "#8B96A0", fontFamily: "IBM Plex Mono, monospace" }}>
        {label}
      </label>
      {children}
      {hint && <p className="text-xs mt-1" style={{ color: "#5E6A73" }}>{hint}</p>}
    </div>
  );
}

const inputStyle = { background: "#101619", border: "1px solid #26323a", color: "#EDEAE3" };

export default function VoltageDropApp() {
  const reportRef = useRef(null);
  const [generandoPDF, setGenerandoPDF] = useState(false);

  const [fase, setFase] = useState("mono");
  const [material, setMaterial] = useState("cobre");
  const [modoCarga, setModoCarga] = useState("corriente");
  const [corriente, setCorriente] = useState(20);
  const [potencia, setPotencia] = useState(4400);
  const [voltaje, setVoltaje] = useState(220);
  const [cosphi, setCosphi] = useState(0.93);
  const [longitud, setLongitud] = useState(25);
  const [modoSeccion, setModoSeccion] = useState("manual");
  const [unidadSeccion, setUnidadSeccion] = useState("mm2"); // mm2 | awg
  const [seccion, setSeccion] = useState(4);
  const [canalizacion, setCanalizacion] = useState("tuberia");
  const [incluirReactancia, setIncluirReactancia] = useState(false);
  const [limiteId, setLimiteId] = useState("circuito");
  const [limiteCustom, setLimiteCustom] = useState(3);
  const [tipoCarga, setTipoCarga] = useState("general");

  const esTrifasico = fase === "tri";

  useEffect(() => {
    setVoltaje(esTrifasico ? 380 : 220);
  }, [fase]);

  const limiteSeleccionado = limiteId === "custom" ? Number(limiteCustom) || 0 : LIMITES.find((l) => l.id === limiteId).valor;
  const canalIdx = CANALIZACIONES.find((c) => c.id === canalizacion).idx;

  const I = useMemo(() => {
    if (modoCarga === "corriente") return Number(corriente) || 0;
    const P = Number(potencia) || 0;
    const V = Number(voltaje) || 1;
    const cp = Number(cosphi) || 1;
    return esTrifasico ? P / (Math.sqrt(3) * V * cp) : P / (V * cp);
  }, [modoCarga, corriente, potencia, voltaje, cosphi, esTrifasico]);

  const rho = MATERIALES[material].resistividad;
  const factorAmp = MATERIALES[material].factorAmpacidad;
  const L = Number(longitud) || 0;
  const cp = Number(cosphi) || 0;
  const sp = Math.sqrt(1 - Math.min(cp, 1) ** 2);
  const factorFase = esTrifasico ? Math.sqrt(3) : 2;

  const calcularDeltaV = (S) => {
    const R = (rho * L) / S;
    const X = incluirReactancia ? REACTANCIA_X0 * L : 0;
    return factorFase * I * (R * cp + X * sp);
  };

  const deltaVMaxVoltios = (limiteSeleccionado / 100) * voltaje;
  const rAt1 = rho * L;
  const xAt1 = incluirReactancia ? REACTANCIA_X0 * L : 0;
  const calcAt1 = factorFase * I * (rAt1 * cp + xAt1 * sp);

  const porCaida = seccionPorCaida(deltaVMaxVoltios, calcAt1);
  const porAmpacidad = seccionPorAmpacidad(I, canalIdx, factorAmp);
  const sugerida = Math.max(porCaida.s, porAmpacidad.s);
  const criterioGobernante = porAmpacidad.s >= porCaida.s ? "ampacidad" : "caida";

  const seccionEfectiva = modoSeccion === "sugerir" ? sugerida : seccion;
  const deltaVFinal = calcularDeltaV(seccionEfectiva);
  const pctFinal = (deltaVFinal / voltaje) * 100;
  const cumple = pctFinal <= limiteSeleccionado;

  const capacidadSeccionEfectiva = AMPACIDAD_CU[seccionEfectiva]
    ? AMPACIDAD_CU[seccionEfectiva][canalIdx] * factorAmp
    : null;
  const ampacidadOk = capacidadSeccionEfectiva === null ? true : capacidadSeccionEfectiva >= I;

  // ---- Selección de termomagnético: Ib ≤ In ≤ Iz ----
  const cargaSeleccionada = TIPOS_CARGA.find((t) => t.id === tipoCarga);
  const iz = capacidadSeccionEfectiva; // capacidad admisible del conductor (A)
  const candidatosIn = IN_STANDARD.filter((v) => v >= I);
  const inRecomendado =
    (iz ? candidatosIn.find((v) => v <= iz) : candidatosIn[0]) ??
    candidatosIn[0] ??
    IN_STANDARD[IN_STANDARD.length - 1];
  const proteccionOk = iz ? inRecomendado <= iz : true;
  const margenIn = (inRecomendado / I).toFixed(2);

  // ---- Generación de PDF ----
  const generarPDF = async () => {
    if (!reportRef.current) return;
    setGenerandoPDF(true);
    try {
      const canvas = await html2canvas(reportRef.current, {
        scale: 2,
        backgroundColor: "#101619",
        useCORS: true,
      });
      const imgData = canvas.toDataURL("image/png");
      const pdf = new jsPDF({
        orientation: canvas.width > canvas.height ? "landscape" : "portrait",
        unit: "mm",
        format: "a4",
      });
      const pdfWidth = pdf.internal.pageSize.getWidth();
      const pdfHeight = pdf.internal.pageSize.getHeight();
      const ratio = Math.min(pdfWidth / canvas.width, pdfHeight / canvas.height) * 100;
      pdf.addImage(imgData, "PNG", 0, 0, pdfWidth, pdfHeight);
      
      const fecha = new Date().toLocaleString("es-CL");
      pdf.setFontSize(8);
      pdf.text(`Generado: ${fecha}`, 10, pdfHeight - 5);
      
      pdf.save(`caida-tension-RIC4_${new Date().getTime()}.pdf`);
    } catch (err) {
      console.error("Error generando PDF:", err);
      alert("Error al generar el PDF. Intenta de nuevo.");
    } finally {
      setGenerandoPDF(false);
    }
  };

  return (
    <div className="min-h-screen w-full" style={{ background: "#101619", fontFamily: "Inter, sans-serif" }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@500;600;700&family=Inter:wght@400;500;600&family=IBM+Plex+Mono:wght@400;500;600&display=swap');
        input[type=range]::-webkit-slider-thumb { -webkit-appearance: none; width: 14px; height: 14px; border-radius: 2px; background: #D98A3D; cursor: pointer; margin-top: -5px; }
        input[type=range] { -webkit-appearance: none; height: 4px; background: #26323a; border-radius: 2px; }
        select { appearance: none; }
      `}</style>

      <header className="border-b" style={{ borderColor: "#1F2A30" }}>
        <div className="max-w-5xl mx-auto px-6 py-6 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 flex items-center justify-center rounded-full overflow-hidden" style={{ background: "#ffffff", border: "1px solid #26323a" }}>
              <img src={LOGO_TAU} alt="TAU Soluciones Eléctricas" className="w-full h-full object-cover" />
            </div>
            <div>
              <h1 className="text-lg font-semibold tracking-tight" style={{ fontFamily: "Space Grotesk, sans-serif", color: "#EDEAE3" }}>
                Caída de Tensión · RIC N°4
              </h1>
              <p className="text-xs" style={{ color: "#5E6A73" }}>Circuitos monofásicos y trifásicos en baja tensión</p>
            </div>
          </div>
          <button
            onClick={generarPDF}
            disabled={generandoPDF}
            className="px-4 py-2 rounded-lg text-sm font-medium transition-all flex items-center gap-2"
            style={{
              background: generandoPDF ? "#26323a" : "#D98A3D",
              color: "#101619",
              cursor: generandoPDF ? "wait" : "pointer",
              opacity: generandoPDF ? 0.6 : 1,
            }}
          >
            <Download size={14} />
            {generandoPDF ? "Generando..." : "Descargar PDF"}
          </button>
        </div>
      </header>

      <main className="max-w-5xl mx-auto px-6 py-8 grid grid-cols-1 lg:grid-cols-5 gap-6" ref={reportRef}>
        <section className="lg:col-span-3 rounded-lg p-5" style={{ background: "#171F24", border: "1px solid #26323a" }}>
          <div className="flex items-center gap-2 mb-5">
            <Settings2 size={15} color="#8B96A0" />
            <h2 className="text-sm font-medium tracking-wide uppercase" style={{ color: "#8B96A0", fontFamily: "IBM Plex Mono, monospace" }}>
              Parámetros del circuito
            </h2>
          </div>

          <Field label="Tipo de sistema">
            <div className="grid grid-cols-2 gap-2">
              {[{ id: "mono", label: "Monofásico · 220V" }, { id: "tri", label: "Trifásico · 380V" }].map((opt) => (
                <button key={opt.id} onClick={() => setFase(opt.id)} className="py-2.5 rounded text-sm transition-colors"
                  style={{ background: fase === opt.id ? "#2A2118" : "#101619", border: `1px solid ${fase === opt.id ? "#B8722E" : "#26323a"}`, color: fase === opt.id ? "#D98A3D" : "#8B96A0" }}>
                  {opt.label}
                </button>
              ))}
            </div>
          </Field>

          <Field label="Material del conductor">
            <div className="grid grid-cols-2 gap-2">
              {Object.entries(MATERIALES).map(([key, m]) => (
                <button key={key} onClick={() => setMaterial(key)} className="py-2.5 rounded text-sm transition-colors flex items-center justify-center gap-2"
                  style={{ background: material === key ? "#1E2329" : "#101619", border: `1px solid ${material === key ? m.color : "#26323a"}`, color: material === key ? m.color : "#8B96A0" }}>
                  <Cable size={13} /> {m.nombre}
                </button>
              ))}
            </div>
          </Field>

          <Field label="Dato de carga disponible">
            <div className="grid grid-cols-2 gap-2 mb-3">
              {[{ id: "corriente", label: "Corriente (A)" }, { id: "potencia", label: "Potencia (W)" }].map((opt) => (
                <button key={opt.id} onClick={() => setModoCarga(opt.id)} className="py-2 rounded text-xs"
                  style={{ background: modoCarga === opt.id ? "#1E2329" : "transparent", border: `1px solid ${modoCarga === opt.id ? "#3A4650" : "#26323a"}`, color: modoCarga === opt.id ? "#EDEAE3" : "#5E6A73" }}>
                  {opt.label}
                </button>
              ))}
            </div>
            {modoCarga === "corriente" ? (
              <input type="number" value={corriente} onChange={(e) => setCorriente(e.target.value)} className="w-full px-3 py-2 rounded text-sm" style={inputStyle} />
            ) : (
              <input type="number" value={potencia} onChange={(e) => setPotencia(e.target.value)} className="w-full px-3 py-2 rounded text-sm" style={inputStyle} />
            )}
          </Field>

          <div className="grid grid-cols-2 gap-4">
            <Field label="Tensión nominal (V)">
              <input type="number" value={voltaje} onChange={(e) => setVoltaje(e.target.value)} className="w-full px-3 py-2 rounded text-sm" style={inputStyle} />
            </Field>
            <Field label="Factor de potencia (cos φ)">
              <input type="number" step="0.01" min="0" max="1" value={cosphi} onChange={(e) => setCosphi(e.target.value)} className="w-full px-3 py-2 rounded text-sm" style={inputStyle} />
            </Field>
          </div>

          <Field label={`Longitud del circuito: ${longitud} m`}>
            <input type="range" min="1" max="200" value={longitud} onChange={(e) => setLongitud(e.target.value)} className="w-full" />
          </Field>

          {/* Tipo de canalización */}
          <Field label="Tipo de canalización" hint="Afecta la capacidad de corriente admisible del conductor (ampacidad).">
            <div className="grid grid-cols-3 gap-2">
              {CANALIZACIONES.map((c) => (
                <button key={c.id} onClick={() => setCanalizacion(c.id)} className="py-2.5 rounded text-xs flex flex-col items-center gap-1 text-center"
                  style={{ background: canalizacion === c.id ? "#1E2329" : "#101619", border: `1px solid ${canalizacion === c.id ? "#B8722E" : "#26323a"}`, color: canalizacion === c.id ? "#D98A3D" : "#8B96A0" }}>
                  <Layers size={13} />
                  {c.nombre}
                </button>
              ))}
            </div>
          </Field>

          {/* Sección */}
          <Field label="Sección del conductor">
            <div className="grid grid-cols-2 gap-2 mb-2">
              {[{ id: "manual", label: "Ingresar sección" }, { id: "sugerir", label: "Sugerir sección" }].map((opt) => (
                <button key={opt.id} onClick={() => setModoSeccion(opt.id)} className="py-2 rounded text-xs"
                  style={{ background: modoSeccion === opt.id ? "#1E2329" : "transparent", border: `1px solid ${modoSeccion === opt.id ? "#3A4650" : "#26323a"}`, color: modoSeccion === opt.id ? "#EDEAE3" : "#5E6A73" }}>
                  {opt.label}
                </button>
              ))}
            </div>

            {modoSeccion === "manual" && (
              <div className="grid grid-cols-2 gap-2 mb-2">
                {[{ id: "mm2", label: "mm²" }, { id: "awg", label: "AWG / kcmil" }].map((opt) => (
                  <button key={opt.id} onClick={() => setUnidadSeccion(opt.id)} className="py-1.5 rounded text-xs"
                    style={{ background: unidadSeccion === opt.id ? "#26323a" : "transparent", border: "1px solid #26323a", color: unidadSeccion === opt.id ? "#EDEAE3" : "#5E6A73" }}>
                    {opt.label}
                  </button>
                ))}
              </div>
            )}

            {modoSeccion === "manual" ? (
              unidadSeccion === "mm2" ? (
                <select value={seccion} onChange={(e) => setSeccion(Number(e.target.value))} className="w-full px-3 py-2 rounded text-sm" style={inputStyle}>
                  {SECCIONES_MM2.map((s) => <option key={s} value={s}>{s} mm²</option>)}
                </select>
              ) : (
                <select value={seccion} onChange={(e) => setSeccion(Number(e.target.value))} className="w-full px-3 py-2 rounded text-sm" style={inputStyle}>
                  {AWG_TABLE.map((a) => <option key={a.awg} value={a.mm2}>{a.awg} AWG ({a.mm2.toFixed(1)} mm²)</option>)}
                </select>
              )
            ) : (
              <div className="px-3 py-2 rounded text-sm flex items-center justify-between" style={inputStyle}>
                <span style={{ color: "#5E6A73" }}>Sección mínima calculada</span>
                <span style={{ color: "#D98A3D", fontFamily: "IBM Plex Mono, monospace" }}>
                  {sugerida} mm² · {mm2ToAwg(sugerida)} AWG
                </span>
              </div>
            )}
            {modoSeccion === "sugerir" && (
              <p className="text-xs mt-1.5" style={{ color: "#5E6A73" }}>
                Criterio gobernante: {criterioGobernante === "ampacidad" ? "capacidad de corriente (ampacidad)" : "caída de tensión"}
                {" · "}caída exige ≥{porCaida.s} mm², ampacidad exige ≥{porAmpacidad.s} mm²
              </p>
            )}
          </Field>

          <div className="flex items-center justify-between py-2 px-3 rounded" style={{ background: "#101619", border: "1px solid #26323a" }}>
            <span className="text-xs" style={{ color: "#8B96A0" }}>Incluir reactancia inductiva (X ≈ 0.08 Ω/km)</span>
            <button onClick={() => setIncluirReactancia(!incluirReactancia)} className="w-10 h-5 rounded-full relative transition-colors"
              style={{ background: incluirReactancia ? "#B8722E" : "#26323a" }}>
              <span className="absolute top-0.5 w-4 h-4 rounded-full bg-white transition-all" style={{ left: incluirReactancia ? "22px" : "2px" }} />
            </button>
          </div>

          <div className="mt-5">
            <Field label="Límite normativo de referencia">
              <div className="relative">
                <select value={limiteId} onChange={(e) => setLimiteId(e.target.value)} className="w-full px-3 py-2 rounded text-sm appearance-none" style={inputStyle}>
                  {LIMITES.map((l) => <option key={l.id} value={l.id}>{l.nombre}</option>)}
                </select>
                <ChevronDown size={14} className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none" color="#5E6A73" />
              </div>
              {limiteId === "custom" && (
                <input type="number" step="0.1" value={limiteCustom} onChange={(e) => setLimiteCustom(e.target.value)} className="w-full px-3 py-2 rounded text-sm mt-2" style={inputStyle} placeholder="% límite" />
              )}
            </Field>
          </div>

          {/* Tipo de carga → curva del termomagnético */}
          <Field label="Tipo de carga del circuito" hint="Determina la curva de disparo magnético recomendada para el termomagnético.">
            <div className="grid grid-cols-1 gap-2">
              {TIPOS_CARGA.map((t) => (
                <button key={t.id} onClick={() => setTipoCarga(t.id)} className="py-2.5 px-3 rounded text-sm flex items-center justify-between text-left"
                  style={{ background: tipoCarga === t.id ? "#1E2329" : "#101619", border: `1px solid ${tipoCarga === t.id ? "#B8722E" : "#26323a"}`, color: tipoCarga === t.id ? "#EDEAE3" : "#8B96A0" }}>
                  <span>{t.nombre}</span>
                  <span style={{ color: "#D98A3D", fontFamily: "IBM Plex Mono, monospace" }}>Curva {t.curva}</span>
                </button>
              ))}
            </div>
          </Field>
        </section>

        <section className="lg:col-span-2 flex flex-col gap-4">
          <div className="rounded-lg p-5" style={{ background: "#171F24", border: "1px solid #26323a" }}>
            <div className="flex items-center gap-2 mb-3">
              <Gauge size={15} color="#8B96A0" />
              <h2 className="text-sm font-medium tracking-wide uppercase" style={{ color: "#8B96A0", fontFamily: "IBM Plex Mono, monospace" }}>
                Resultado
              </h2>
            </div>
            <Gauge2 pct={pctFinal} limite={limiteSeleccionado || 0.01} />
            <div className="text-center mt-1">
              <p className="text-xs" style={{ color: "#5E6A73" }}>límite de referencia: {limiteSeleccionado}%</p>
            </div>

            <div className="mt-4 flex items-center gap-2 px-3 py-2.5 rounded"
              style={{ background: cumple ? "#16241C" : "#291A17", border: `1px solid ${cumple ? "#2E4A38" : "#4A2C25"}` }}>
              {cumple ? <CheckCircle2 size={16} color="#4F9B72" /> : <AlertTriangle size={16} color="#C1503F" />}
              <span className="text-sm" style={{ color: cumple ? "#4F9B72" : "#C1503F" }}>
                {cumple ? "Cumple con el límite de caída de tensión" : "Excede el límite de caída de tensión"}
              </span>
            </div>

            {capacidadSeccionEfectiva !== null && (
              <div className="mt-2 flex items-center gap-2 px-3 py-2.5 rounded"
                style={{ background: ampacidadOk ? "#16241C" : "#291A17", border: `1px solid ${ampacidadOk ? "#2E4A38" : "#4A2C25"}` }}>
                {ampacidadOk ? <CheckCircle2 size={16} color="#4F9B72" /> : <AlertTriangle size={16} color="#C1503F" />}
                <span className="text-sm" style={{ color: ampacidadOk ? "#4F9B72" : "#C1503F" }}>
                  {ampacidadOk ? "Cumple con la ampacidad admisible" : "Corriente supera la ampacidad admisible"}
                </span>
              </div>
            )}

            <div className="grid grid-cols-2 gap-3 mt-4">
              <div className="rounded p-3" style={{ background: "#101619", border: "1px solid #26323a" }}>
                <p className="text-xs mb-1" style={{ color: "#5E6A73" }}>ΔV</p>
                <p className="text-lg" style={{ fontFamily: "IBM Plex Mono, monospace", color: "#EDEAE3" }}>{deltaVFinal.toFixed(2)} V</p>
              </div>
              <div className="rounded p-3" style={{ background: "#101619", border: "1px solid #26323a" }}>
                <p className="text-xs mb-1" style={{ color: "#5E6A73" }}>Corriente</p>
                <p className="text-lg" style={{ fontFamily: "IBM Plex Mono, monospace", color: "#EDEAE3" }}>{I.toFixed(1)} A</p>
              </div>
              <div className="rounded p-3" style={{ background: "#101619", border: "1px solid #26323a" }}>
                <p className="text-xs mb-1" style={{ color: "#5E6A73" }}>Sección usada</p>
                <p className="text-lg" style={{ fontFamily: "IBM Plex Mono, monospace", color: "#EDEAE3" }}>{seccionEfectiva} mm²</p>
                <p className="text-xs" style={{ color: "#5E6A73" }}>{mm2ToAwg(seccionEfectiva)} AWG aprox.</p>
              </div>
              <div className="rounded p-3" style={{ background: "#101619", border: "1px solid #26323a" }}>
                <p className="text-xs mb-1" style={{ color: "#5E6A73" }}>Tensión en carga</p>
                <p className="text-lg" style={{ fontFamily: "IBM Plex Mono, monospace", color: "#EDEAE3" }}>{(voltaje - deltaVFinal).toFixed(1)} V</p>
              </div>
            </div>

            {capacidadSeccionEfectiva !== null && (
              <div className="mt-3 rounded p-3" style={{ background: "#101619", border: "1px solid #26323a" }}>
                <p className="text-xs mb-1" style={{ color: "#5E6A73" }}>Ampacidad admisible ({CANALIZACIONES.find(c=>c.id===canalizacion).nombre})</p>
                <p className="text-lg" style={{ fontFamily: "IBM Plex Mono, monospace", color: "#EDEAE3" }}>{capacidadSeccionEfectiva.toFixed(0)} A</p>
              </div>
            )}
          </div>

          {/* Termomagnético recomendado */}
          <div className="rounded-lg p-5" style={{ background: "#171F24", border: "1px solid #26323a" }}>
            <div className="flex items-center gap-2 mb-3">
              <ShieldCheck size={15} color="#8B96A0" />
              <h2 className="text-sm font-medium tracking-wide uppercase" style={{ color: "#8B96A0", fontFamily: "IBM Plex Mono, monospace" }}>
                Termomagnético recomendado
              </h2>
            </div>

            <div className="flex items-center justify-between px-3 py-3 rounded mb-3" style={{ background: "#101619", border: "1px solid #26323a" }}>
              <div>
                <p className="text-xs" style={{ color: "#5E6A73" }}>Corriente nominal (In)</p>
                <p className="text-xl" style={{ fontFamily: "IBM Plex Mono, monospace", color: "#EDEAE3" }}>{inRecomendado} A</p>
              </div>
              <div className="text-right">
                <p className="text-xs" style={{ color: "#5E6A73" }}>Curva de disparo</p>
                <p className="text-xl" style={{ fontFamily: "IBM Plex Mono, monospace", color: "#D98A3D" }}>Curva {cargaSeleccionada.curva}</p>
              </div>
            </div>

            <p className="text-xs leading-relaxed mb-3" style={{ color: "#8B96A0" }}>{cargaSeleccionada.desc}</p>
            <p className="text-xs mb-3" style={{ color: "#5E6A73" }}>
              Disparo instantáneo en el rango <span style={{ color: "#D98A3D", fontFamily: "IBM Plex Mono, monospace" }}>{cargaSeleccionada.rango}</span> de In.
            </p>

            <div className="rounded p-3 mb-2" style={{ background: "#101619", border: "1px solid #26323a" }}>
              <p className="text-xs mb-1" style={{ color: "#5E6A73" }}>Verificación de coordinación</p>
              <p className="text-sm" style={{ fontFamily: "IBM Plex Mono, monospace", color: "#EDEAE3" }}>
                Ib {I.toFixed(1)} A ≤ In {inRecomendado} A {iz ? `≤ Iz ${iz.toFixed(0)} A` : ""}
              </p>
              <p className="text-xs mt-1" style={{ color: "#5E6A73" }}>margen sobre corriente de diseño: ×{margenIn}</p>
            </div>

            <div className="flex items-center gap-2 px-3 py-2.5 rounded"
              style={{ background: proteccionOk ? "#16241C" : "#291A17", border: `1px solid ${proteccionOk ? "#2E4A38" : "#4A2C25"}` }}>
              {proteccionOk ? <CheckCircle2 size={16} color="#4F9B72" /> : <AlertTriangle size={16} color="#C1503F" />}
              <span className="text-sm" style={{ color: proteccionOk ? "#4F9B72" : "#C1503F" }}>
                {proteccionOk
                  ? "La protección coordina correctamente con el conductor"
                  : "In supera Iz: aumenta la sección del conductor para proteger correctamente el circuito"}
              </span>
            </div>
          </div>

          <div className="rounded-lg p-5" style={{ background: "#171F24", border: "1px solid #26323a" }}>
            <h3 className="text-xs font-medium tracking-wide uppercase mb-3" style={{ color: "#8B96A0", fontFamily: "IBM Plex Mono, monospace" }}>
              Fórmula aplicada
            </h3>
            <p className="text-sm leading-relaxed" style={{ fontFamily: "IBM Plex Mono, monospace", color: "#D98A3D" }}>
              ΔV = {esTrifasico ? "√3" : "2"} · I · (R·cos φ {incluirReactancia ? "+ X·sen φ" : ""})
            </p>
            <p className="text-xs mt-2" style={{ color: "#5E6A73" }}>
              R = ρ·L / S, con ρ({MATERIALES[material].nombre.toLowerCase()}) = {rho} Ω·mm²/m a temperatura de servicio.
            </p>
          </div>

          <p className="text-xs leading-relaxed px-1" style={{ color: "#4A555E" }}>
            Los valores de resistividad, ampacidad por tipo de canalización, curvas de termomagnético y límites porcentuales
            corresponden a criterios orientativos de aplicación habitual del pliego RIC N°4. Son referencias aproximadas:
            verifica siempre contra la tabla oficial vigente de la norma y las curvas del fabricante del disyuntor (que
            consideran aislación, agrupamiento, temperatura ambiente y coordinación con protecciones aguas arriba) antes de
            usar estos resultados en un proyecto real.
          </p>
        </section>
      </main>
    </div>
  );
}
